#include <bits/stdc++.h>
using namespace std;struct P{double x,y;};struct Key{long long x,y;bool operator==(Key const&o)const{return x==o.x&&y==o.y;}};struct KH{size_t operator()(Key const&k)const{return hash<long long>()(k.x*1000003LL+k.y);}};Key key(P a){return{llround(a.x*1e8),llround(a.y*1e8)};}double ds(P a,P b){return hypot(a.x-b.x,a.y-b.y);} 
int main(int ac,char**av){if(ac<7){cerr<<"coords macro fixed model_list candidates out\n";return 2;}ifstream fc(av[1]),fm(av[2]),ffi(av[3]),fl(av[4]),fin(av[5]);ofstream out(av[6]);int n,m;fc>>n;vector<P>C(n);for(auto&p:C)fc>>p.x>>p.y;fm>>m;vector<P>M(m);for(auto&p:M)fm>>p.x>>p.y;vector<int>fixed(n);int x;while(ffi>>x)if(0<=x&&x<n)fixed[x]=1;vector<string>paths;string s;while(fl>>s)paths.push_back(s);int R=paths.size();vector<vector<unsigned char>> cols(R,vector<unsigned char>(n));for(int r=0;r<R;r++){ifstream f(paths[r]);int z;for(int i=0;i<n;i++){if(!(f>>z)){cerr<<"bad model "<<paths[r]<<" i="<<i<<"\n";return 3;}cols[r][i]=z;}}
unordered_map<Key,int,KH>idx;for(int i=0;i<n;i++)idx[key(C[i])]=i;double cell=1.05;unordered_map<long long,vector<int>>grid;auto gk=[&](int a,int b){return((long long)a<<32)^(unsigned)b;};for(int i=0;i<n;i++)if(fixed[i])grid[gk(floor(C[i].x/cell),floor(C[i].y/cell))].push_back(i);vector<pair<int,int>>U;for(int i=0;i<m;i++)for(int j=i+1;j<m;j++)if(fabs(ds(M[i],M[j])-1)<3e-7)U.push_back({i,j});
auto incompatible=[&](vector<P>const&A,vector<int>const&old,int r)->bool{auto &col=cols[r];vector<int>var(m,-1),vars;for(int i=0;i<m;i++)if(old[i]<0||!fixed[old[i]]){var[i]=vars.size();vars.push_back(i);}int q=vars.size();if(q==0){for(auto[i,j]:U)if(col[old[i]]==col[old[j]])return true;return false;}vector<int>mask(q,31);vector<vector<int>>adj(q);for(int aa=0;aa<q;aa++){int i=vars[aa];P z=A[i];int bx=floor(z.x/cell),by=floor(z.y/cell),forb=0;for(int dx=-1;dx<=1;dx++)for(int dy=-1;dy<=1;dy++){auto it=grid.find(gk(bx+dx,by+dy));if(it==grid.end())continue;for(int v:it->second)if(fabs(ds(z,C[v])-1)<3e-7)forb|=1<<col[v];}mask[aa]&=~forb;if(!mask[aa])return true;}for(auto[i,j]:U){int a=var[i],b=var[j];if(a>=0&&b>=0){adj[a].push_back(b);adj[b].push_back(a);}else if(a>=0){mask[a]&=~(1<<col[old[j]]);}else if(b>=0){mask[b]&=~(1<<col[old[i]]);}else if(col[old[i]]==col[old[j]])return true;}for(int a=0;a<q;a++)if(!mask[a])return true;vector<int>as(q,-1);function<bool(int)>dfs=[&](int left){if(!left)return true;int best=-1,bm=0,bc=99;for(int a=0;a<q;a++)if(as[a]<0){int mm=mask[a];for(int b:adj[a])if(as[b]>=0)mm&=~(1<<as[b]);int c=__builtin_popcount((unsigned)mm);if(c<bc){bc=c;best=a;bm=mm;if(c<=1)break;}}if(!bm)return false;while(bm){int bit=bm&-bm;bm-=bit;as[best]=__builtin_ctz((unsigned)bit);if(dfs(left-1))return true;as[best]=-1;}return false;};return !dfs(q);};
string line;int li=0;while(getline(fin,line)){if(line.empty())continue;istringstream z(line);string K;int rov,rfov;z>>K>>rov>>rfov;vector<P>A(m);for(auto&p:A)z>>p.x>>p.y;vector<int>old(m,-1),support;int ov=0,fov=0;for(int i=0;i<m;i++){auto it=idx.find(key(A[i]));if(it!=idx.end()&&ds(A[i],C[it->second])<4e-7){old[i]=it->second;ov++;if(fixed[old[i]]){fov++;support.push_back(old[i]);}}}int kill=0;uint64_t mask=0;for(int r=0;r<R;r++)if(incompatible(A,old,r)){kill++;if(r<64)mask|=1ULL<<r;}sort(support.begin(),support.end());support.erase(unique(support.begin(),support.end()),support.end());out<<li<<" "<<kill<<" "<<R<<" "<<ov<<" "<<fov<<" "<<(m-ov)<<" "<<mask<<" ";for(int v:support)out<<v<<",";out<<"\n";li++;}cerr<<"evaluated "<<li<<" candidates on "<<R<<" models\n";}
